(()=>{const e=document.querySelector(".language-switch");if(!e)return;const t=e.querySelector("summary");document.addEventListener("pointerdown",t=>{e.contains(t.target)||(e.open=!1)}),document.addEventListener("keydown",n=>{n.key==="Escape"&&e.open&&(e.open=!1,t.focus())}),e.addEventListener("focusout",t=>{e.contains(t.relatedTarget)||(e.open=!1)}),window.addEventListener("pageshow",t=>{t.persisted&&(e.open=!1)})})()